const { useState } = React;

function App() {
  const [page, setPage] = useState("cart");
  const [coupon, setCoupon] = useState("");
  const [couponError, setCouponError] = useState("");

  const items = [
    { id: 1, name: "Linen shirt", price: 40, photoKey: "product" },
    { id: 2, name: "Straw hat", price: 80, photoKey: "product" },
  ];

  const total = items.reduce((sum, item) => sum + item.price, 0);

  function handleCheckout() {
    // Simple validation: coupon code must be empty or at least 3 chars
    if (coupon && coupon.trim().length < 3) {
      setCouponError("Coupon code must be at least 3 characters.");
      return;
    }
    setCouponError("");
    setPage("checkout");
  }

  if (page === "checkout") {
    return (
      <main style={styles.main}>
        <h1 style={styles.title}>Checkout</h1>
        <p style={{ marginTop: 20 }}>
          Thank you for your purchase! Your total is <strong>${total}</strong>.
        </p>
        <button style={styles.button} onClick={() => setPage("cart")}>Back to Cart</button>
      </main>
    );
  }

  return (
    <main style={styles.main}>
      <h1 style={styles.title}>Your cart</h1>

      <section aria-label="Shopping cart items" style={styles.itemsSection}>
        {items.map(({ id, name, price, photoKey }) => (
          <article key={id} style={styles.itemCard}>
            <img
              src={`/runtime/photos/${photoKey}.jpg`}
              alt={name}
              style={styles.thumbnail}
              width={64}
              height={64}
              loading="lazy"
            />
            <div style={styles.itemInfo}>
              <p style={styles.itemName}>{name}</p>
              <p style={styles.itemPrice}>${price}</p>
            </div>
          </article>
        ))}
      </section>

      <div style={styles.totalRow}>
        <span>Total</span>
        <span>${total}</span>
      </div>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          handleCheckout();
        }}
        style={styles.form}
        noValidate
      >
        <label htmlFor="coupon" style={styles.label}>
          Coupon code
        </label>
        <input
          id="coupon"
          name="coupon"
          type="text"
          value={coupon}
          onChange={(e) => setCoupon(e.target.value)}
          style={styles.input}
          aria-describedby={couponError ? "coupon-error" : undefined}
        />
        {couponError && (
          <p id="coupon-error" role="alert" style={styles.error}>
            {couponError}
          </p>
        )}

        <button type="submit" style={styles.button}>
          Checkout
        </button>
        <a href="#" onClick={(e) => { e.preventDefault(); /* no navigation needed, just placeholder */ }} style={styles.continueLink}>
          Continue shopping
        </a>
      </form>
    </main>
  );
}

const styles = {
  main: {
    maxWidth: 360,
    margin: "20px auto",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif",
    color: "#222",
    padding: 16,
  },
  title: {
    fontWeight: "normal",
    fontSize: 24,
    marginBottom: 16,
  },
  itemsSection: {
    display: "flex",
