    gap: 12,
    marginBottom: 16,
  },
  itemCard: {
    display: "flex",
    alignItems: "center",
    border: "1px solid #ccc",
    borderRadius: 6,
    padding: 8,
  },
  thumbnail: {
    borderRadius: 4,
    objectFit: "cover",
    flexShrink: 0,
  },
  itemInfo: {
    marginLeft: 12,
